/**
 * Operator-facing wording for the costing console. Persian, and — like
 * `CostingMessages` — never containing a cost figure, because messages reach
 * logs and clients.
 *
 * The idempotency key is generated by the Admin client once per submission and
 * resent verbatim on a retry; an operator never types it, and the messages say
 * what the CLIENT must do.
 */
export const CostingConsoleMessages = Object.freeze({
  IDEMPOTENCY_KEY_REQUIRED:
    'سرآیند Idempotency-Key الزامی است؛ برنامهٔ مدیریت باید برای هر ثبت یک کلید یکتا بسازد و در تکرار همان درخواست، همان کلید را بفرستد.',
  IDEMPOTENCY_KEY_INVALID:
    'Idempotency-Key نامعتبر است؛ باید ۸ تا ۲۰۰ نویسه و فقط شامل حروف لاتین، ارقام و . _ : - باشد.',
  IDEMPOTENCY_KEY_REUSED:
    'این کلید تکرار قبلاً برای درخواست دیگری استفاده شده است؛ برای ثبت جدید کلید تازه بسازید.',
  IDEMPOTENCY_REQUEST_IN_PROGRESS:
    'درخواستی با همین کلید در حال انجام است؛ کمی بعد دوباره تلاش کنید.',
  VARIANT_NOT_FOUND: 'گونهٔ محصول پیدا نشد.',
  PRODUCT_NOT_FOUND: 'محصول پیدا نشد.',
});
